package com.umc.pediupatrao.audit; import org.springframework.web.bind.annotation.*; import java.util.List; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.http.ResponseEntity;
@RestController @RequestMapping("/api/auditoria") @PreAuthorize("hasAnyRole('ADMIN','GERENTE')") public class AuditoriaController {private final AuditoriaService service; public AuditoriaController(AuditoriaService service){this.service=service;} @GetMapping public List<Auditoria> listar(){return service.listar();} @PostMapping @PreAuthorize("denyAll()") public ResponseEntity<Void> criar(){return ResponseEntity.status(405).build();} @PutMapping("/{id}") @PreAuthorize("denyAll()") public ResponseEntity<Void> editar(){return ResponseEntity.status(405).build();} @DeleteMapping("/{id}") @PreAuthorize("denyAll()") public ResponseEntity<Void> excluir(){return ResponseEntity.status(405).build();}}
